static IEnumerable<int> EvenNumbers(int max) // lazy: runs on foreach
{
    ArgumentOutOfRangeException.ThrowIfNegative(max); // eager validation runs NOW
    return Core();
    static IEnumerable<int> Core() // deferred part
    {
        for (int i = 0; i <= max; i += 2) { yield return i; }
    }
}

