LinkedList<string> order = new LinkedList<string>();
Dictionary<string, LinkedListNode<string>> index = new Dictionary<string, LinkedListNode<string>>();

void Touch(string key) // move to front: O(1)
{
    if (index.TryGetValue(key, out LinkedListNode<string>? node)) { order.Remove(node); }
    else if (index.Count >= 100) // evict tail
    {
        string last = order.Last!.Value;
        order.RemoveLast();
        index.Remove(last);
    }
    index[key] = order.AddFirst(key);
}
